solution:
export class Pair<A, B> {
  constructor(public first: A, public second: B) {}

  swap(): Pair<B, A> {
    return new Pair(this.second, this.first);
  }

  map<C>(fn: (a: A) => C): Pair<C, B> {
    return new Pair(fn(this.first), this.second);
  }
}
